package com.restaurantmanagement.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="orders", uniqueConstraints=@UniqueConstraint(name="uk_external_order_source_restaurant", columnNames={"externalOrderId","platform","restaurant_id"})) public class CustomerOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; @Column(nullable=false) public String externalOrderId; @Column(nullable=false) public String platform; @ManyToOne(optional=false) public Restaurant restaurant; @Column(nullable=false) public String customerName; @Column(nullable=false, precision=12, scale=2) public BigDecimal total; @Enumerated(EnumType.STRING) @Column(nullable=false) public OrderStatus status=OrderStatus.NEW; @Column(nullable=false, unique=true) public String idempotencyKey; public LocalDateTime createdAt=LocalDateTime.now(); public LocalDateTime updatedAt=LocalDateTime.now(); }
